// @deno-types="npm:@types/babel__helper-validator-identifier@7.15.2"
import { isIdentifierName } from 'npm:@babel/helper-validator-identifier@7.22.20'
import { camelCase } from 'npm:lodash-es@4.17.21'
import { match } from 'npm:ts-pattern@5.2.0'

type ListArgs<V> = {
  items: V[]
  bookends: 'square' | 'curly' | 'round' | 'none'
  separator: string
  renderWhenEmpty?: boolean
}

type ToArrayArgs<V> = {
  items: V[]
  renderWhenEmpty?: boolean
}

type ToObjectArgs<V> = {
  items: V[]
  renderWhenEmpty?: boolean
}

type KeysToObjectArgs<V> = {
  record?: Record<string, unknown>
  map?: (value: string) => V
  renderWhenEmpty?: boolean
}

export class List<V> {
  bookends: 'square' | 'curly' | 'round' | 'none'
  separator: string
  renderWhenEmpty: boolean
  items: V[] = []
  constructor({
    items,
    bookends,
    separator,
    renderWhenEmpty = true
  }: ListArgs<V>) {
    this.items = items
    this.bookends = bookends
    this.separator = separator
    this.renderWhenEmpty = renderWhenEmpty
  }

  static toArray<V>(args: ToArrayArgs<V>) {
    return new List({ ...args, bookends: 'square', separator: ',' })
  }

  static toObject<V>(args: ToObjectArgs<V>) {
    return new List({ ...args, bookends: 'curly', separator: ',' })
  }

  static keysToObject<V>({
    record,
    map,
    renderWhenEmpty
  }: KeysToObjectArgs<V>) {
    const items = Object.keys(record ?? {}).map(key => (map ? map(key) : key))

    return new List({
      items,
      bookends: 'curly',
      separator: ',',
      renderWhenEmpty
    })
  }

  toString() {
    if (this.items.length === 0 && !this.renderWhenEmpty) {
      return ''
    }

    const items = this.items.map(item => `${item}`).join(this.separator)

    return match(this.bookends)
      .with('square', () => `[${items}]`)
      .with('curly', () => `{${items}}`)
      .with('round', () => `(${items})`)
      .with('none', () => items)
      .exhaustive()
  }
}

export class ObjectProperty {
  name: string
  isValid: boolean
  canonicalName: string
  constructor(name: string) {
    this.name = name
    this.isValid = isIdentifierName(name)
    this.canonicalName = this.isValid ? name : camelCase(name)

    if (!isIdentifierName(this.canonicalName)) {
      throw new Error(
        `Property name '${name}' is not a valid identifier and cannot be converted to a canonical name`
      )
    }
  }

  toString(): string {
    return this.isValid ? this.name : `${this.name}: ${this.canonicalName}`
  }
}

