 */
export type TypeSystemCustom = {
  /** Discriminator for the custom type */
  type: 'custom'
  /** The custom type value to be rendered */
  value: Stringable
  /** Optional generator-specific key for tracking */
  generatorKey?: GeneratorKey
}

