    output: TypeSystemNumber
  }
  void: {
    source: OasVoid
    output: TypeSystemVoid
  }
  integer: {
    source: OasSchema
    output: TypeSystemInteger
  }
  boolean: {
    source: OasSchema
    output: TypeSystemBoolean
  }
  unknown: {
    source: OasSchema
    output: TypeSystemUnknown
  }
  null: {
    source: OasSchema
    output: TypeSystemNull
  }
  object: {
